def eval_task(self, agent_responses: List[str]) -> Tuple[bool, Dict[str, Any]]:
    ans = ["Rachel", "T. Gannon"]
    success = True if all(x in agent_responses[0] for x in ans) else False
    return success, {"agent_responses": agent_responses}

